import { describe, expect, it } from 'vitest';
import {
  BAND_ICD_MS,
  BAND_PROC_CHANCE,
  warlockItemBuffs,
} from '../../src/data/classes/warlock/buffs';
import { itemDbSync } from '../../src/data/items/dbSync';
import type { ItemDb, ItemProcEffect, ItemRecord, ItemUseEffect } from '../../src/data/items/types';
import type { RawStats } from '../../src/engine/types';

// Structured on-use and proc effects of the item database (gear item effects, Task 1). Generated by
// `npm run db:build -- <wowsims tbc-new clone>` (scripts/build-item-db.mjs) from tbc-new @ 91f869a
// assets/database/db.json `itemEffects`; proc triggers from the Go registrations (PROC_TRIGGERS in
// the generator). See docs/data-sources.md, "Part F: gear item effects".

const db: ItemDb = itemDbSync();
const items: ItemRecord[] = Object.values(db.items);

/** The RawStats keys an item effect may carry (the modelled ones; never baseMana). */
const EFFECT_STATS: readonly (keyof RawStats)[] = [
  'intellect',
  'spirit',
  'spellPower',
  'shadowPower',
  'firePower',
  'critRating',
  'hitRating',
  'hasteRating',
  'mp5',
];
const TRIGGERS = ['cast', 'hit', 'crit'] as const;

/** An effect text line that names a modelled stat (the generator prints only modelled stats). */
const MODELLED_STAT_TEXT =
  /\+[\d.]+ (Intellect|Spirit|spell damage|shadow damage|fire damage|hit rating|crit rating|haste rating|mana per 5 s)\b/;

/**
 * Effects that carry a modelled stat but stay text, by item id, with the reason. Every other
 * on-use or proc effect with a modelled stat must be structured (useEffects / procEffects).
 */
const TEXT_ONLY_STAT_EFFECTS: Readonly<Record<number, string>> = {
  19337: 'The Black Book: a pet buff (its attack power and armor are not modelled)',
  21473: 'Eye of Moam: +100 spell penetration (not modelled) with the spell damage',
  22678: 'Talisman of Ascendance: stacks per spell (stacking is not modelled)',
  28727: 'Pendant of the Violet Eye: stacks per spell (stacking is not modelled)',
  28190: 'Scarab of the Infinite Cycle: procs from heals only',
  28789: 'Eye of Magtheridon: procs on a resisted spell (wowsims OutcomeMiss)',
  31856: 'Darkmoon Card: Crusade: stacks (and a melee half)',
  31857: 'Darkmoon Card: Wrath: stacks, melee and spell crit',
  32493: 'Ashtongue Talisman of Shadows: procs on Corruption ticks (periodic damage)',
  32771: "Airman's Ribbon of Gallantry: procs on a killing blow (not implemented in wowsims)",
};

/**
 * Every structured proc and its trigger, read from wowsims tbc-new @ 91f869a
 * sim/common/tbc/stat_bonus_procs_auto_gen.go (Callback, ProcMask, Outcome and the tooltip line):
 * OnSpellHitDealt + OutcomeCrit -> 'crit'; OnSpellHitDealt + OutcomeLanded -> 'hit';
 * OnCastComplete + ProcMaskSpellDamage: 'hit' when the tooltip says the spell must land or hit
 * (the stage F Band rule), else 'cast'.
 */
const PROC_TRIGGER_TABLE: Readonly<Record<number, (typeof TRIGGERS)[number]>> = {
  21190: 'hit', // Wrath of Cenarius: "when your harmful spells land"
  24122: 'cast', // Coronet of Verdant Flame: "on successful spellcast"
  24123: 'cast', // Circlet of Arcane Might: "on successful spellcast"
  27683: 'cast', // Quagmirran's Eye: "Your harmful spells have a chance"
  28418: 'crit', // Shiffar's Nexus-Horn: "Chance on spell critical hit" (OutcomeCrit)
  28578: 'cast', // Masquerade Gown: "Chance on spell cast"
  28602: 'hit', // Robe of the Elder Scribes: "when your harmful spells land"
  29305: 'hit', // Band of the Eternal Sage: "chance on hit"
  29309: 'hit', // Band of the Eternal Restorer: OnSpellHitDealt, OutcomeLanded
  30626: 'crit', // Sextant of Unstable Currents: "Your spell critical strikes" (OutcomeCrit)
  31336: 'cast', // Blade of Wizardry: "Your harmful spells have a chance"
  32496: 'cast', // Memento of Tyrande: "Each time you cast a spell"
};

const allUse = (): [ItemRecord, ItemUseEffect][] =>
  items.flatMap((i) => (i.useEffects ?? []).map((e): [ItemRecord, ItemUseEffect] => [i, e]));
const allProc = (): [ItemRecord, ItemProcEffect][] =>
  items.flatMap((i) => (i.procEffects ?? []).map((e): [ItemRecord, ItemProcEffect] => [i, e]));

describe('structured item effects in the database', () => {
  it('Icon of the Silver Crescent (29370): useEffect +155 spell power, 20000 ms, cooldown 120000, group 1141 / 20000', () => {
    // db.json 29370 itemEffects[0]: buffId 35163 "Blessing of the Silver Crescent (35163)",
    // effectDurationMs 20000, stats {4: 155 healing, 5: 155 spell damage}, onUse {cooldownMs 120000,
    // categoryId 1141, categoryCooldownMs 20000}; stat_bonus_cds_auto_gen.go NewSimpleStatActive(29370).
    const icon = db.items[29370]!;
    expect(icon.useEffects).toEqual([
      {
        buffName: 'Blessing of the Silver Crescent',
        buffId: 35163,
        stats: { spellPower: 155 },
        durationMs: 20000,
        cooldownMs: 120000,
        group: { id: 1141, ms: 20000 },
      },
    ]);
    expect(icon.procEffects).toBeUndefined();
    // Its only effect is structured: no unmodelled text left.
    expect(icon.effects).toBeUndefined();

    // The same numbers as the hand-modelled stage 1.5 / F entry.
    const hand = warlockItemBuffs.find((b) => b.id === 'icon-of-the-silver-crescent')!;
    const use = icon.useEffects![0]!;
    expect(use.cooldownMs).toBe(hand.effect.action!.cooldownMs);
    expect(use.group!.ms).toBe(hand.effect.action!.sharedCooldown!.ms);
    expect(use.durationMs).toBe(hand.effect.selfAura!.durationMs);
    expect(use.stats).toEqual(hand.effect.selfAura!.selfStatBonuses);
    expect(use.buffName).toBe(hand.effect.selfAura!.name);
    expect(use.buffId).toBe(hand.effect.selfAura!.wowheadId);
  });

  it("Band of the Eternal Sage (29305): procEffect +95 spell power, 10000 ms, chance 0.1, icd 60000, trigger 'hit'", () => {
    // db.json 29305: buffId 35084 "Band of the Eternal Sage (35083)", effectDurationMs 10000,
    // stats {4: 95, 5: 95}, proc {icdMs 60000, procChance 0.1}. wowsims registers it with
    // CallbackOnCastComplete + ProcMaskSpellDamage ("Your offensive spells have a chance on hit");
    // the trainer's stage F rule rolls it on a landed damaging spell: trigger 'hit'.
    const band = db.items[29305]!;
    expect(band.procEffects).toEqual([
      {
        buffName: 'Band of the Eternal Sage',
        buffId: 35084,
        stats: { spellPower: 95 },
        durationMs: 10000,
        chance: 0.1,
        icdMs: 60000,
        trigger: 'hit',
      },
    ]);
    expect(band.useEffects).toBeUndefined();
    expect(band.effects).toBeUndefined();

    const hand = warlockItemBuffs.find((b) => b.id === 'band-of-the-eternal-sage')!;
    const buff = hand.effect.auras!.find((a) => a.id === 'band-of-the-eternal-sage')!;
    const proc = band.procEffects![0]!;
    expect(proc.chance).toBe(BAND_PROC_CHANCE);
    expect(proc.icdMs).toBe(BAND_ICD_MS);
    expect(proc.durationMs).toBe(buff.durationMs);
    expect(proc.stats).toEqual(buff.selfStatBonuses);
    expect(proc.buffId).toBe(buff.wowheadId);
  });

  it("Quagmirran's Eye (27683): proc +320 haste 6000 ms chance 0.1 icd 45000, trigger 'cast'", () => {
    // db.json 27683: buffId 33370 "Spell Haste (33297)", 6000 ms, stats {14: 320}, proc {icdMs 45000,
    // procChance 0.1}; stat_bonus_procs_auto_gen.go: CallbackOnCastComplete, ProcMaskSpellDamage,
    // "Your harmful spells have a chance to increase your spell haste rating by 320 for 6 secs."
    expect(db.items[27683]!.procEffects).toEqual([
      { buffName: 'Spell Haste', buffId: 33370, stats: { hasteRating: 320 }, durationMs: 6000, chance: 0.1, icdMs: 45000, trigger: 'cast' },
    ]);
    expect(db.items[27683]!.effects).toBeUndefined();
  });

  it("Call of the Nexus (buff 34321) is Shiffar's Nexus-Horn (28418): +225 spell power 10000 ms, chance 0.2, icd 45000, trigger 'crit'", () => {
    // No item 34321: it is the buff spell. db.json 28418: buffId 34321 "Call of the Nexus (34320)",
    // 10000 ms, stats {4: 225, 5: 225}, proc {icdMs 45000, procChance 0.2};
    // stat_bonus_procs_auto_gen.go: CallbackOnSpellHitDealt | CallbackOnHealDealt, OutcomeCrit,
    // "Chance on spell critical hit to increase your spell damage and healing by 225 for 10 secs."
    expect(db.items[34321]).toBeUndefined();
    expect(db.items[28418]).toMatchObject({ name: "Shiffar's Nexus-Horn", slot: 'trinket' });
    expect(db.items[28418]!.procEffects).toEqual([
      { buffName: 'Call of the Nexus', buffId: 34321, stats: { spellPower: 225 }, durationMs: 10000, chance: 0.2, icdMs: 45000, trigger: 'crit' },
    ]);
  });

  it('an item with a modelled and an unmodelled effect keeps the unmodelled one as text: Bangle of Endless Blessings (28370)', () => {
    // db.json 28370: a proc "Meditation (38334)" (no stat: spirit-based regen while casting, not a
    // stat buff) and an on-use "Endless Blessings" +130 spirit 20 s, 2 min, no category
    // (categoryCooldownMs -1); stat_bonus_cds_auto_gen.go NewSimpleStatActive(28370).
    const bangle = db.items[28370]!;
    expect(bangle.useEffects).toEqual([
      { buffName: 'Endless Blessings', buffId: 34210, stats: { spirit: 130 }, durationMs: 20000, cooldownMs: 120000 },
    ]);
    expect(bangle.procEffects).toBeUndefined();
    expect(bangle.effects).toEqual(['Proc: Meditation (15 s)']);
  });

  it('a modelled effect is never also listed as text', () => {
    for (const item of items) {
      const texts = item.effects ?? [];
      for (const e of item.useEffects ?? []) {
        expect(texts.some((t) => t.startsWith(`On use: ${e.buffName}`)), `${item.id} ${item.name}`).toBe(false);
      }
      for (const e of item.procEffects ?? []) {
        expect(texts.some((t) => t.startsWith(`Proc: ${e.buffName}`)), `${item.id} ${item.name}`).toBe(false);
      }
      // Fields stay sparse: never an empty list.
      if (item.effects) expect(item.effects.length, `${item.id} effects`).toBeGreaterThan(0);
      if (item.useEffects) expect(item.useEffects.length, `${item.id} useEffects`).toBeGreaterThan(0);
      if (item.procEffects) expect(item.procEffects.length, `${item.id} procEffects`).toBeGreaterThan(0);
    }
  });

  it('every on-use or proc effect with a modelled stat is structured, or is one of the listed text-only effects', () => {
    const textWithStat = items.filter((i) => (i.effects ?? []).some((t) => /^(On use|Proc): /.test(t) && MODELLED_STAT_TEXT.test(t)));
    expect(textWithStat.map((i) => i.id).sort((a, b) => a - b)).toEqual(
      Object.keys(TEXT_ONLY_STAT_EFFECTS).map(Number).sort((a, b) => a - b),
    );
  });

  it('every on-use effect has positive duration and cooldown, a positive shared group, and modelled stats', () => {
    const uses = allUse();
    expect(uses.length).toBeGreaterThan(0);
    for (const [item, e] of uses) {
      const label = `${item.id} ${item.name}`;
      expect(e.durationMs, label).toBeGreaterThan(0);
      expect(e.cooldownMs, label).toBeGreaterThan(0);
      expect(Number.isInteger(e.durationMs) && Number.isInteger(e.cooldownMs), label).toBe(true);
      if (e.group) {
        expect(e.group.id, label).toBeGreaterThan(0);
        expect(e.group.ms, label).toBeGreaterThan(0);
      }
      expect(e.buffName.length, label).toBeGreaterThan(0);
      expect(e.buffName, label).not.toMatch(/\(\d+\)$/);
    }
    // Every on-use trinket with a stat buff the trainer models has its useEffect.
    const trinketsWithUseText = items.filter(
      (i) => i.slot === 'trinket' && (i.effects ?? []).some((t) => t.startsWith('On use: ') && MODELLED_STAT_TEXT.test(t)),
    );
    for (const i of trinketsWithUseText) expect(Object.hasOwn(TEXT_ONLY_STAT_EFFECTS, i.id), `${i.id} ${i.name}`).toBe(true);
  });

  it('every proc effect has a trigger in the allowed set, a chance in (0, 1], an ICD >= 0 and a positive duration', () => {
    const procs = allProc();
    for (const [item, e] of procs) {
      const label = `${item.id} ${item.name}`;
      expect(TRIGGERS, label).toContain(e.trigger);
      expect(e.chance, label).toBeGreaterThan(0);
      expect(e.chance, label).toBeLessThanOrEqual(1);
      expect(e.icdMs, label).toBeGreaterThanOrEqual(0);
      expect(e.durationMs, label).toBeGreaterThan(0);
      expect(e.buffName.length, label).toBeGreaterThan(0);
    }
    const triggers = Object.fromEntries(procs.map(([i, e]) => [i.id, e.trigger]));
    expect(triggers).toEqual(PROC_TRIGGER_TABLE);
  });

  it('effect stats use only modelled RawStats keys with positive values', () => {
    for (const [item, e] of [...allUse(), ...allProc()]) {
      const entries = Object.entries(e.stats);
      expect(entries.length, `${item.id} ${item.name}`).toBeGreaterThan(0);
      for (const [stat, value] of entries) {
        expect(EFFECT_STATS, `${item.id} ${item.name} ${stat}`).toContain(stat);
        expect(value, `${item.id} ${item.name} ${stat}`).toBeGreaterThan(0);
      }
    }
  });

  it('counts are pinned', () => {
    const uses = allUse();
    const procs = allProc();
    expect(uses).toHaveLength(31);
    expect(uses.filter(([, e]) => e.group !== undefined)).toHaveLength(20);
    expect(uses.filter(([i]) => i.slot === 'trinket')).toHaveLength(30);
    expect(procs).toHaveLength(12);
    expect(procs.filter(([, e]) => e.trigger === 'cast')).toHaveLength(6);
    expect(procs.filter(([, e]) => e.trigger === 'hit')).toHaveLength(4);
    expect(procs.filter(([, e]) => e.trigger === 'crit')).toHaveLength(2);
    // No item has more than one structured effect of a kind today.
    expect(items.filter((i) => (i.useEffects?.length ?? 0) > 1 || (i.procEffects?.length ?? 0) > 1)).toEqual([]);
    // Items with text left (148 items had effect text before the structured effects).
    expect(items.filter((i) => i.effects !== undefined)).toHaveLength(148 - 43 + 1);
  });
});
